package com.travbook.hotels.adapter.out.persistence;
import com.travbook.hotels.application.port.in.HotelReservations;
import com.travbook.hotels.application.port.out.*;
import com.travbook.shared.domain.DomainFailure;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
public final class DurableMockHotelReservations implements HotelReservations {
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final HotelSupplierGateway pricing;private final HotelRoomStock stock;private final Clock clock;
 public DurableMockHotelReservations(JdbcClient jdbc,TransactionTemplate tx,ObjectMapper json,HotelSupplierGateway pricing,HotelRoomStock stock,Clock clock){this.jdbc=jdbc;this.tx=tx;this.json=json;this.pricing=pricing;this.stock=stock;this.clock=clock;}
 private void lock(String id){jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","hotel-provider:"+id).query(Object.class).single();}
 private Optional<Receipt> receipt(UUID id){return jdbc.sql("select receipt::text from hotel_provider_operation where operation_id=:id").param("id",id).query(String.class).optional().map(v->json.readValue(v,Receipt.class));}
 public Optional<Current> current(UUID id){return tx.execute(t->jdbc.sql("select r.id,r.status,r.reference,(select coalesce(sum(quantity),0) from hotel_room_allocation where reservation_id=r.id and active) as units from hotel_provider_reservation r where r.id=:id").param("id",id).query((r,n)->new Current(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getInt(4),"MOCK")).optional());}
 public Optional<Receipt> lookup(UUID id){return tx.execute(t->{lock(id.toString());return receipt(id);});}
 private Receipt existing(UUID id,Object request){var r=receipt(id).orElseThrow();String stored=jdbc.sql("select request::text from hotel_provider_operation where operation_id=:id").param("id",id).query(String.class).single();if(!json.readTree(stored).equals(json.readTree(json.writeValueAsString(request))))throw new IllegalArgumentException("Hotel provider operation key reused");return r;}
 private Receipt save(UUID op,UUID reservation,String operation,Object request,boolean accepted,String status,String reference){var r=new Receipt(op,reservation,accepted,status,reference,"MOCK");jdbc.sql("insert into hotel_provider_operation(operation_id,reservation_id,operation,request,receipt) values(:id,:reservation,:op,cast(:request as jsonb),cast(:receipt as jsonb))").param("id",op).param("reservation",reservation).param("op",operation).param("request",json.writeValueAsString(request)).param("receipt",json.writeValueAsString(r)).update();return r;}
 public Receipt reserve(Command c){var prior=lookup(c.operationId());if(prior.isPresent())return tx.execute(t->{lock(c.operationId().toString());return existing(c.operationId(),c);});
  boolean valid=!c.reject()&&c.validUntil().isAfter(clock.instant());if(valid){try{var fresh=pricing.reprice(c.criteria(),c.offers(),clock.instant());valid=fresh.size()==c.offers().size();for(int i=0;valid&&i<fresh.size();i++)valid=fresh.get(i).sameTerms(c.offers().get(i));}catch(DomainFailure e){if(e.code()==DomainFailure.Code.OFFER_UNAVAILABLE||e.code()==DomainFailure.Code.OFFER_EXPIRED)valid=false;else throw e;}}
  final boolean priceValid=valid;return tx.execute(t->{String property=c.offers().getFirst().propertyId();lock(property);lock(c.reservationId().toString());lock(c.operationId().toString());if(receipt(c.operationId()).isPresent())return existing(c.operationId(),c);
   boolean available=priceValid&&c.validUntil().isAfter(clock.instant());var groups=new LinkedHashMap<String,Integer>();for(var offer:c.offers()){if(!property.equals(offer.propertyId()))throw new IllegalArgumentException("Mixed property reservation");groups.merge(com.travbook.hotels.adapter.out.supplier.MockRoomPolicy.group(offer.planCode()),1,(a,b)->a+b);}for(var offer:c.offers())if(stock.remaining(property,offer.planCode(),c.criteria().checkIn(),c.criteria().checkOut())<groups.get(com.travbook.hotels.adapter.out.supplier.MockRoomPolicy.group(offer.planCode())))available=false;
   String reference="MOCK-STAY-"+c.reservationId();jdbc.sql("insert into hotel_provider_reservation(id,property_id,status,reference,payload) values(:id,:property,:status,:reference,cast(:payload as jsonb))").param("id",c.reservationId()).param("property",property).param("status",available?"CONFIRMED":"REJECTED").param("reference",reference).param("payload",json.writeValueAsString(c)).update();
   if(available)for(var group:groups.entrySet())for(var day=c.criteria().checkIn();day.isBefore(c.criteria().checkOut());day=day.plusDays(1))jdbc.sql("insert into hotel_room_allocation(reservation_id,property_id,night,room_group,quantity,active) values(:id,:property,:night,:group,:quantity,true)").param("id",c.reservationId()).param("property",property).param("night",day).param("group",group.getKey()).param("quantity",group.getValue()).update();
   return save(c.operationId(),c.reservationId(),"RESERVE",c,available,available?"CONFIRMED":"REJECTED",reference);
  });}
 public Receipt amend(AmendmentCommand a){
  var c=a.replacement();if(!a.operationId().equals(c.operationId())||!a.reservationId().equals(c.reservationId()))throw new IllegalArgumentException("Amendment command binding");
  if(lookup(a.operationId()).isPresent())return tx.execute(t->{lock(a.operationId().toString());return existing(a.operationId(),a);});
  boolean valid=c.validUntil().isAfter(clock.instant());
  if(valid)try{var fresh=pricing.reprice(c.criteria(),c.offers(),clock.instant());valid=fresh.size()==c.offers().size();for(int i=0;valid&&i<fresh.size();i++)valid=fresh.get(i).sameTerms(c.offers().get(i));}catch(DomainFailure e){if(Set.of(DomainFailure.Code.OFFER_UNAVAILABLE,DomainFailure.Code.OFFER_EXPIRED,DomainFailure.Code.VALIDATION_FAILED).contains(e.code()))valid=false;else throw e;}
  final boolean fresh=valid;
  return tx.execute(t->{String property=c.offers().getFirst().propertyId();lock(property);lock(c.reservationId().toString());lock(c.operationId().toString());if(receipt(c.operationId()).isPresent())return existing(c.operationId(),a);
   var stored=jdbc.sql("select payload::text from hotel_provider_reservation where id=:id and property_id=:property and status='CONFIRMED' for update").param("id",c.reservationId()).param("property",property).query(String.class).optional().orElseThrow(()->new IllegalStateException("Current reservation outcome unknown"));var before=json.readValue(stored,Command.class);
   if(!before.criteria().equals(a.previousCriteria())||!before.offers().stream().map(o->o.id()).toList().equals(a.previousOfferIds()))throw new IllegalStateException("Provider reservation revision mismatch");
   boolean available=fresh&&a.previousCriteria().checkIn().atTime(14,0).atZone(ZoneId.of("Asia/Kolkata")).toInstant().isAfter(clock.instant())&&c.validUntil().isAfter(clock.instant())&&before.criteria().rooms().equals(c.criteria().rooms())&&before.offers().size()==c.offers().size()&&!(c.criteria().checkIn().isBefore(before.criteria().checkOut())&&before.criteria().checkIn().isBefore(c.criteria().checkOut()));
   var groups=new LinkedHashMap<String,Integer>();for(int i=0;i<c.offers().size();i++){var o=c.offers().get(i);if(!property.equals(o.propertyId())||!o.paymentCondition().equals("MOCK_PAY_AT_PROPERTY")||o.planCode()!=com.travbook.hotels.domain.model.HotelOffer.Plan.FLEX||!before.offers().get(i).paymentCondition().equals("MOCK_PAY_AT_PROPERTY"))available=false;groups.merge(com.travbook.hotels.adapter.out.supplier.MockRoomPolicy.group(o.planCode()),1,(left,right)->left+right);}
   for(var o:c.offers())if(stock.remaining(property,o.planCode(),c.criteria().checkIn(),c.criteria().checkOut())<groups.get(com.travbook.hotels.adapter.out.supplier.MockRoomPolicy.group(o.planCode())))available=false;
   if(available){jdbc.sql("update hotel_room_allocation set active=false where reservation_id=:id").param("id",c.reservationId()).update();for(var group:groups.entrySet())for(var day=c.criteria().checkIn();day.isBefore(c.criteria().checkOut());day=day.plusDays(1))jdbc.sql("insert into hotel_room_allocation(reservation_id,property_id,night,room_group,quantity,active) values(:id,:property,:night,:group,:quantity,true) on conflict(reservation_id,night,room_group) do update set quantity=excluded.quantity,active=true").param("id",c.reservationId()).param("property",property).param("night",day).param("group",group.getKey()).param("quantity",group.getValue()).update();jdbc.sql("update hotel_provider_reservation set payload=cast(:payload as jsonb) where id=:id").param("payload",json.writeValueAsString(c)).param("id",c.reservationId()).update();}
   return save(c.operationId(),c.reservationId(),"AMEND",a,available,available?"CONFIRMED":"REJECTED","MOCK-STAY-"+c.reservationId());
  });
 }
 public Receipt change(ChangeCommand a){
  var c=a.replacement();if(!a.operationId().equals(c.operationId())||!a.reservationId().equals(c.reservationId()))throw new IllegalArgumentException("Amendment command binding");
  if(lookup(a.operationId()).isPresent())return tx.execute(t->{lock(a.operationId().toString());return existing(a.operationId(),a);});
  boolean valid=c.validUntil().isAfter(clock.instant());if(a.guests().isEmpty()||a.guests().size()>20)throw new IllegalArgumentException("Complete guest manifest required");
  if(valid)try{var fresh=pricing.changeRates(c.reservationId(),c.offers().getFirst().propertyId(),c.criteria(),c.offers().stream().map(o->o.planCode()).toList(),c.offers().stream().map(o->o.id()).toList(),c.offers().getFirst().paymentCondition().equals("MOCK_PAY_AT_PROPERTY"),clock.instant());valid=fresh.size()==c.offers().size();for(int i=0;valid&&i<fresh.size();i++)valid=fresh.get(i).sameTerms(c.offers().get(i));}catch(DomainFailure e){if(Set.of(DomainFailure.Code.OFFER_UNAVAILABLE,DomainFailure.Code.OFFER_EXPIRED,DomainFailure.Code.VALIDATION_FAILED).contains(e.code()))valid=false;else throw e;}
  final boolean fresh=valid;
  return tx.execute(t->{String property=c.offers().getFirst().propertyId();lock(property);lock(c.reservationId().toString());lock(c.operationId().toString());if(receipt(c.operationId()).isPresent())return existing(c.operationId(),a);
   var stored=jdbc.sql("select payload::text from hotel_provider_reservation where id=:id and property_id=:property and status='CONFIRMED' for update").param("id",c.reservationId()).param("property",property).query(String.class).optional().orElseThrow(()->new IllegalStateException("Current reservation outcome unknown"));var before=json.readValue(stored,Command.class);
   if(!before.criteria().equals(a.previousCriteria())||!before.offers().stream().map(o->o.id()).toList().equals(a.previousOfferIds()))throw new IllegalStateException("Provider reservation revision mismatch");
   boolean available=fresh&&a.previousCriteria().checkIn().atTime(14,0).atZone(ZoneId.of("Asia/Kolkata")).toInstant().isAfter(clock.instant())&&c.validUntil().isAfter(clock.instant())&&!c.reject()&&before.offers().stream().allMatch(o->o.paymentCondition().equals("MOCK_PAY_AT_PROPERTY")||o.refundable()&&o.freeCancellationUntil()!=null&&o.freeCancellationUntil().isAfter(clock.instant()));
   var groups=new LinkedHashMap<String,Integer>();for(int i=0;i<c.offers().size();i++){var o=c.offers().get(i);if(!property.equals(o.propertyId())||!o.paymentCondition().equals(before.offers().getFirst().paymentCondition())||!o.supplier().equals(before.offers().getFirst().supplier()))available=false;groups.merge(com.travbook.hotels.adapter.out.supplier.MockRoomPolicy.group(o.planCode()),1,(left,right)->left+right);}
   for(var o:c.offers())if(stock.remaining(property,o.planCode(),c.criteria().checkIn(),c.criteria().checkOut(),c.reservationId())<groups.get(com.travbook.hotels.adapter.out.supplier.MockRoomPolicy.group(o.planCode())))available=false;
   if(available){jdbc.sql("update hotel_room_allocation set active=false where reservation_id=:id").param("id",c.reservationId()).update();for(var group:groups.entrySet())for(var day=c.criteria().checkIn();day.isBefore(c.criteria().checkOut());day=day.plusDays(1))jdbc.sql("insert into hotel_room_allocation(reservation_id,property_id,night,room_group,quantity,active) values(:id,:property,:night,:group,:quantity,true) on conflict(reservation_id,night,room_group) do update set quantity=excluded.quantity,active=true").param("id",c.reservationId()).param("property",property).param("night",day).param("group",group.getKey()).param("quantity",group.getValue()).update();jdbc.sql("update hotel_provider_reservation set payload=cast(:payload as jsonb) where id=:id").param("payload",json.writeValueAsString(c)).param("id",c.reservationId()).update();}
   var receipt=save(c.operationId(),c.reservationId(),"CHANGE",a,available,available?"CONFIRMED":"REJECTED","MOCK-STAY-"+c.reservationId());if(available)jdbc.sql("update hotel_provider_reservation set guest_operation_id=:op where id=:id").param("op",c.operationId()).param("id",c.reservationId()).update();return receipt;
  });
 }
 public Receipt cancel(UUID operation,UUID reservation){var request=Map.of("operationId",operation,"reservationId",reservation);return tx.execute(t->{String property=jdbc.sql("select property_id from hotel_provider_reservation where id=:id").param("id",reservation).query(String.class).optional().orElseThrow(()->new IllegalStateException("Reservation outcome unknown"));lock(property);lock(reservation.toString());lock(operation.toString());if(receipt(operation).isPresent())return existing(operation,request);String reference=jdbc.sql("select reference from hotel_provider_reservation where id=:id for update").param("id",reservation).query(String.class).single();jdbc.sql("update hotel_provider_reservation set status='CANCELLED' where id=:id").param("id",reservation).update();jdbc.sql("update hotel_room_allocation set active=false where reservation_id=:id").param("id",reservation).update();return save(operation,reservation,"CANCEL",request,true,"CANCELLED",reference);});}
}
